// Xác thực tài khoản người vận hành CAHY CyberWatch trực tiếp trên PostgreSQL (bảng app_users / profiles)
const body = $input.first().json.body || $input.first().json || {};
const email = String(body.email || '').trim().toLowerCase();
const password = String(body.password || '');
const client = String(body.client || 'cahy-cyberwatch');
const PG_API = ($env.POSTGRES_API_URL || 'http://postgres_api:5434').replace(/\/+$/, '');

if (!email || !password) {
  return [{ json: { statusCode: 400, payload: { ok: false, error: 'Thiếu email hoặc mật khẩu.' } } }];
}

try {
  const authRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `${PG_API}/api/auth/login`,
    headers: { 'Content-Type': 'application/json' },
    body: { email, password },
    json: true,
  });

  return [{
    json: {
      statusCode: 200,
      payload: {
        ok: true,
        provider: 'postgresql',
        client,
        issued_at: new Date().toISOString(),
        access_token: authRes.access_token,
        user: authRes.user,
      },
    },
  }];
} catch (e) {
  return [{
    json: {
      statusCode: 401,
      payload: {
        ok: false,
        error: 'Email hoặc mật khẩu không chính xác (PostgreSQL RBAC).',
      },
    },
  }];
}

const body = $input.first().json.body || $input.first().json || {};
const headers = $input.first().json.headers || {};
const PG_API = ($env.POSTGRES_API_URL || 'http://postgres_api:5434').replace(/\/+$/, '');

let pendingQueueCount = 0;
try {
  const qRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `${PG_API}/api/news-queue?status=pending`,
    json: true,
  });
  if (typeof qRes?.count === 'number') pendingQueueCount = qRes.count;
  else if (Array.isArray(qRes?.data)) pendingQueueCount = qRes.data.length;
} catch {}

return [{
  json: {
    ok: true,
    engine: 'localhost-n8n-postgresql',
    message: `Đã phát lệnh quét chủ động (${body.target || 'all'}) cho kênh ${body.channel || 'ANTT'} trên PostgreSQL (hàng đợi chờ: ${pendingQueueCount})`,
    target: body.target || 'all',
    channel: body.channel || 'ANTT',
    pendingQueueCount,
    requestedBy: headers['x-cahy-user'] || 'operator',
    triggeredAt: new Date().toISOString()
  }
}];

const body = $input.first().json.body || $input.first().json || {};
const period = ['day', 'week', 'month'].includes(body.period) ? body.period : 'day';
const rawChannel = String(body.channel || 'ANTT');
const dbChannel = rawChannel === 'Phản Động' || rawChannel === 'PhanDong' ? 'PhanDong' : 'ANTT';

const PG_API = ($env.POSTGRES_API_URL || 'http://postgres_api:5434').replace(/\/+$/, '');
const OPENAI_API_KEY = $env.OPENAI_API_KEY || '';
const OPENAI_BASE_URL = ($env.OPENAI_BASE_URL || 'https://api.openai.com/v1').replace(/\/+$/, '');
const OPENAI_MODEL = $env.OPENAI_MODEL || 'gpt-4o-mini';

const pad = (n) => String(n).padStart(2, '0');
const fmtLocal = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;

const now = new Date();
const days = period === 'day' ? 1 : period === 'week' ? 7 : 30;
const start = new Date(now.getTime() - days * 86400000);
const periodStart = fmtLocal(start);
const periodEnd = fmtLocal(now);

let articles = [];
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `${PG_API}/api/news/paginated?page=1&limit=200&channel=${encodeURIComponent(dbChannel)}&startDate=${encodeURIComponent(periodStart)}`,
    json: true,
  });
  if (Array.isArray(res?.data)) articles = res.data;
} catch {}

let positive = 0, negative = 0, neutral = 0;
const kwMap = {};
for (const a of articles) {
  const sName = a.sentiment?.name || '';
  if (sName === 'Tích cực') positive++;
  else if (sName === 'Tiêu cực') negative++;
  else neutral++;
  if (a.keywords) {
    for (const rawKw of String(a.keywords).split(',')) {
      const kw = rawKw.trim();
      if (kw) kwMap[kw] = (kwMap[kw] || 0) + 1;
    }
  }
}

const topKeywords = Object.entries(kwMap)
  .map(([keyword, count]) => ({ keyword, count }))
  .sort((a, b) => b.count - a.count)
  .slice(0, 12);

const stats = {
  total: articles.length,
  positive,
  negative,
  neutral,
  top_keywords: topKeywords,
};

const sampleSummaries = articles
  .slice(0, 18)
  .map((a, idx) => `${idx + 1}. [${a.sentiment?.name || 'Trung lập'}] ${a.summary || ''}`)
  .join('\n');

let reportContent = `### Báo cáo Tổng hợp Xu hướng (${period.toUpperCase()} - ${dbChannel})\n\n- **Tổng số tin bài**: ${stats.total} (Tích cực: ${positive}, Trung lập: ${neutral}, Tiêu cực: ${negative})\n- **Từ khóa trọng tâm**: ${topKeywords.map(k => `${k.keyword} (${k.count})`).join(', ') || 'Chưa phát sinh từ khóa mới'}`;

if (OPENAI_API_KEY) {
  try {
    const aiRes = await this.helpers.httpRequest({
      method: 'POST',
      url: `${OPENAI_BASE_URL}/chat/completions`,
      headers: {
        Authorization: `Bearer ${OPENAI_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: {
        model: OPENAI_MODEL,
        messages: [
          {
            role: 'system',
            content: 'Bạn là chuyên gia phân tích thông tin không gian mạng của Công an tỉnh Hưng Yên. Hãy viết báo cáo xu hướng chuyên nghiệp bằng tiếng Việt (định dạng Markdown rõ ràng, súc tích, không dùng emoji).',
          },
          {
            role: 'user',
            content: `Phân tích báo cáo kỳ ${period} (${periodStart} -> ${periodEnd}) cho kênh ${dbChannel}.\nThống kê: Tổng ${stats.total} bài (Tích cực: ${positive}, Tiêu cực: ${negative}, Trung lập: ${neutral}).\nTừ khóa nổi bật: ${topKeywords.map(k => `${k.keyword} (${k.count})`).join(', ') || 'Không có'}.\nTóm tắt các tin bài tiêu biểu:\n${sampleSummaries || 'Không phát sinh bài viết mới trong khung giờ này.'}\n\nHãy trình bày 4 mục:\n1. Đánh giá tổng quan tình hình\n2. Chủ đề & điểm nóng đáng chú ý\n3. Phân tích sắc thái thông tin\n4. Kiến nghị công tác nắm tình hình & tham mưu xử lý.`,
          },
        ],
      },
      json: true,
    });
    const generated = aiRes?.choices?.[0]?.message?.content;
    if (generated) reportContent = generated;
  } catch {}
}

let savedId = null;
try {
  const inserted = await this.helpers.httpRequest({
    method: 'POST',
    url: `${PG_API}/api/trend-reports`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      period,
      period_start: periodStart,
      period_end: periodEnd,
      channel: dbChannel,
      content: reportContent,
      stats,
    },
    json: true,
  });
  if (inserted?.data?.id) savedId = inserted.data.id;
} catch {}

return [{
  json: {
    ok: true,
    reportId: savedId,
    period,
    channel: dbChannel,
    period_start: periodStart,
    period_end: periodEnd,
    stats,
    message: `Đã tổng hợp và lưu báo cáo xu hướng (${period}) vào PostgreSQL cho kênh ${dbChannel} (${stats.total} tin bài).`
  }
}];

const fs = require('fs');
const path = require('path');

const query = $input.first().json.query || {};
const relPath = String(query.path || query.file || '').replace(/^[/\\]+/, '');
const baseDir = path.resolve($env.FOXPROFILE_SCREENSHOT_DIR || '/screenshots');
const target = path.resolve(baseDir, relPath);

if (!relPath || (!target.startsWith(baseDir + path.sep) && target !== baseDir) || !fs.existsSync(target) || !fs.statSync(target).isFile()) {
  // Return 1x1 transparent PNG if missing so image tags/pipelines never crash
  const emptyPng = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=', 'base64');
  return [{
    json: { found: false, path: relPath },
    binary: {
      data: await this.helpers.prepareBinaryData(emptyPng, 'empty.png', 'image/png'),
    },
  }];
}

const buf = fs.readFileSync(target);
const ext = path.extname(target).toLowerCase();
const mime = ext === '.jpg' || ext === '.jpeg' ? 'image/jpeg' : ext === '.webp' ? 'image/webp' : 'image/png';
return [{
  json: { found: true, path: relPath },
  binary: {
    data: await this.helpers.prepareBinaryData(buf, path.basename(target), mime),
  },
}];
